+(()=>{
+const pieces=[
+ {id:'lift',name:'Lift hill',desc:'Builds big speed',color:'#a7ef70',thrill:5,speed:14,air:0,pts:[[0,0],[26,18],[66,67],[100,86]]},
+ {id:'drop',name:'Big drop',desc:'A stomach-flipping fall',color:'#ff718c',thrill:18,speed:22,air:.8,pts:[[0,0],[20,7],[34,-10],[53,-72],[75,-75],[100,0]]},
+ {id:'loop',name:'Loop-de-loop',desc:'A full 360° inversion',color:'#c299ff',thrill:22,speed:0,air:0,pts:[[0,0],[13,28],[12,62],[25,88],[48,99],[70,92],[86,69],[82,40],[100,0]]},
+ {id:'jump',name:'Canyon jump',desc:'Fly across the gap',color:'#ffbd65',thrill:20,speed:5,air:1.5,pts:[[0,0],[17,13],[36,61],[62,69],[80,24],[100,0]]},
+ {id:'twist',name:'Corkscrew',desc:'Twist through the sky',color:'#6bd9e8',thrill:19,speed:0,air:.2,pts:[[0,0],[20,14],[32,56],[48,76],[68,52],[72,10],[100,0]]},
+ {id:'hill',name:'Airtime hill',desc:'Float on the way down',color:'#f68dce',thrill:11,speed:7,air:.9,pts:[[0,0],[24,28],[50,66],[74,29],[100,0]]},
+ {id:'bank',name:'Banked turn',desc:'Lean into the curve',color:'#7eb4ff',thrill:8,speed:0,air:0,pts:[[0,0],[24,12],[43,23],[66,15],[100,0]]},
+ {id:'brake',name:'Brake run',desc:'Catch your breath',color:'#c8f36a',thrill:2,speed:-9,air:0,pts:[[0,0],[34,2],[68,1],[100,0]]}
+];
+const $=s=>document.querySelector(s), canvas=$('#gameCanvas'),ctx=canvas.getContext('2d');
+let track=[],running=false,progress=0,raf=0,lastTime=0,carSpeed=0,maxSpeed=0,airtime=0,airAccum=0,soundOn=false,toastTimer;
+const colorMap=Object.fromEntries(pieces.map(p=>[p.id,p.color]));
+function makeIcon(piece){let p=piece.pts, minY=Math.min(...p.map(v=>v[1])),maxY=Math.max(...p.map(v=>v[1]));let h=maxY-minY||1;let d=p.map((v,i)=>`${i?'L':'M'} ${5+v[0]*.29} ${27-(v[1]-minY)*20/h}`).join(' ');return `<svg viewBox="0 0 40 32"><path d="${d}" fill="none" stroke="#39445a" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="${piece.color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
+function renderPalette(){ $('#pieceList').innerHTML=pieces.map(p=>`<button class="piece-card" data-piece="${p.id}" aria-label="Add ${p.name}"><span class="piece-art">${makeIcon(p)}</span><span><span class="piece-name">${p.name}</span><span class="piece-desc">${p.desc}</span></span><span class="piece-plus">+</span></button>`).join('');document.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>addPiece(b.dataset.piece));}
+function seedTrack(){track=['lift','drop','hill','loop','bank'].map((id,i)=>({id,key:Date.now()+i}));}
+function addPiece(id){if(running)return;if(track.length>=12){notify('Track limit reached — test your ride or remove a piece.');return}track.push({id,key:Date.now()+Math.random()});updateUI();draw();}
+function removePiece(i){track.splice(i,1);updateUI();draw()}
+function updateUI(){let thrill=42,speed=64,air=1.2;track.forEach(t=>{let p=pieces.find(x=>x.id===t.id);thrill+=p.thrill;speed+=p.speed;air+=p.air});thrill=Math.min(100,thrill);speed=Math.max(24,Math.min(190,speed));air=Math.min(8,air);$('#partCount').textContent=`${track.length} / 12`;
+$('#trackList').innerHTML=track.length?track.map((t,i)=>`<div class="track-row"><span class="track-index">${String(i+1).padStart(2,'0')}</span><span style="color:${colorMap[t.id]}">●</span><span class="row-name">${pieces.find(p=>p.id===t.id).name}</span><button class="remove-btn" data-remove="${i}" aria-label="Remove piece">×</button></div>`).join(''):'<div class="note">Your track is empty. Add a piece above to begin.</div>';
+document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removePiece(+b.dataset.remove));$('#thrillValue').textContent=thrill;$('#thrillMeter').style.width=thrill+'%';$('#thrillTag').textContent=thrill>80?'EXTREME':thrill>60?'THRILLING':'BUILDING';$('#speedValue').textContent=speed;$('#speedMeter').style.width=Math.min(100,speed/1.8)+'%';$('#airValue').textContent=air.toFixed(1);$('#airMeter').style.width=Math.min(100,air/8*100)+'%';$('#testBtn').textContent=track.length?'▶  Test your coaster':'＋  Build a coaster';}
+function route(){let pts=[{x:0,y:0,id:'start'}],x=0;track.forEach((t,index)=>{let p=pieces.find(q=>q.id===t.id);for(let j=1;j<p.pts.length;j++){let v=p.pts[j];pts.push({x:x+v[0],y:v[1],id:t.id,section:index})}x+=100});pts.push({x:x+30,y:0,id:'finish'});return {pts,width:x+30};}
+function smoothPath(points,step=5){let out=[];for(let i=0;i<points.length-1;i++){let p0=points[Math.max(0,i-1)],p1=points[i],p2=points[i+1],p3=points[Math.min(points.length-1,i+2)];let n=Math.max(3,Math.ceil(Math.hypot(p2.x-p1.x,p2.y-p1.y)/step));for(let j=0;j<n;j++){let t=j/n,t2=t*t,t3=t2*t;let x=.5*((2*p1.x)+(-p0.x+p2.x)*t+(2*p0.x-5*p1.x+4*p2.x-p3.x)*t2+(-p0.x+3*p1.x-3*p2.x+p3.x)*t3);let y=.5*((2*p1.y)+(-p0.y+p2.y)*t+(2*p0.y-5*p1.y+4*p2.y-p3.y)*t2+(-p0.y+3*p1.y-3*p2.y+p3.y)*t3);out.push({x,y})}}out.push(points[points.length-1]);return out;}
+let dpr=1,cw=0,ch=0;
+function resize(){let r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);cw=r.width;ch=r.height;canvas.width=Math.round(cw*dpr);canvas.height=Math.round(ch*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
+function roundedRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
+function draw(){if(!ctx||!cw)return;ctx.clearRect(0,0,cw,ch);let g=ctx.createLinearGradient(0,0,0,ch);g.addColorStop(0,'#192a42');g.addColorStop(.58,'#314b60');g.addColorStop(1,'#78917f');ctx.fillStyle=g;ctx.fillRect(0,0,cw,ch);
+// sun and soft clouds
+ctx.fillStyle='#ffdc8d';ctx.globalAlpha=.88;ctx.beginPath();ctx.arc(cw*.78,ch*.21,24,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
+for(let i=0;i<5;i++){let xx=((i*197+60)-(running?progress*.11:0))%(cw+150);if(xx< -90)xx+=cw+150;let yy=ch*(.18+(i%3)*.07);ctx.fillStyle='#d9e7ea';ctx.globalAlpha=.13;ctx.beginPath();ctx.ellipse(xx,yy,37,8,0,0,Math.PI*2);ctx.ellipse(xx+19,yy-5,20,11,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
+// distant park silhouettes
+let ground=ch*.77;ctx.fillStyle='#405a5d';ctx.beginPath();ctx.moveTo(0,ground);for(let x=0;x<=cw+20;x+=20){let y=ground-12-Math.sin((x+(running?progress*.08:0))*.018)*10;ctx.lineTo(x,y)}ctx.lineTo(cw,ch);ctx.lineTo(0,ch);ctx.fill();
+// distant wheel
+let wx=cw*.74,wy=ground-52;ctx.strokeStyle='#c9d5d055';ctx.lineWidth=2;ctx.beginPath();ctx.arc(wx,wy,34,0,Math.PI*2);ctx.stroke();for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.beginPath();ctx.moveTo(wx,wy);ctx.lineTo(wx+34*Math.cos(a),wy+34*Math.sin(a));ctx.stroke()}
+ctx.fillStyle='#32483e';for(let i=0;i<15;i++){let tx=(i*89+12)%(cw+30),ty=ground-10-(i%4)*3;ctx.beginPath();ctx.moveTo(tx,ty-22-(i%3)*4);ctx.lineTo(tx-14,ty+1);ctx.lineTo(tx+14,ty+1);ctx.fill();ctx.fillRect(tx-2,ty,4,10)}
+ctx.fillStyle='#839669';ctx.fillRect(0,ground,cw,ch-ground);ctx.fillStyle='#a1ad7d';ctx.fillRect(0,ground,cw,3);
+const r=route(),smooth=smoothPath(r.pts),maxY=Math.max(100,...smooth.map(p=>p.y));let scale=Math.min((cw-70)/Math.max(r.width,350),(ch-140)/(maxY+100));scale=Math.max(.35,Math.min(1.1,scale));let visibleW=cw/scale;let viewX=running?Math.max(0,Math.min(r.width-visibleW,progress-visibleW*.24)):0;let offsetX=(running?20:(cw-r.width*scale)/2)-viewX*scale;let base=ground-10;
+let sx=x=>offsetX+x*scale, sy=y=>base-y*scale;
+// track supports
+ctx.lineWidth=Math.max(2,scale*4);for(let i=0;i<smooth.length;i+=Math.max(4,Math.floor(20/scale))){let p=smooth[i],xx=sx(p.x),yy=sy(p.y);if(xx< -20||xx>cw+20)continue;if(yy<base-4){ctx.strokeStyle='#24344a';ctx.beginPath();ctx.moveTo(xx,yy+4);ctx.lineTo(xx,base);ctx.stroke();ctx.strokeStyle='#b9c9c1';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(xx-3,base);ctx.lineTo(xx+3,base);ctx.stroke();ctx.lineWidth=Math.max(2,scale*4)}}
+// rails base and color
+ctx.beginPath();smooth.forEach((p,i)=>{let xx=sx(p.x),yy=sy(p.y);if(i===0)ctx.moveTo(xx,yy);else ctx.lineTo(xx,yy)});ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#26344a';ctx.lineWidth=Math.max(8,scale*13);ctx.stroke();ctx.strokeStyle='#d5e0dc';ctx.lineWidth=Math.max(5,scale*8);ctx.stroke();ctx.strokeStyle='#8499a8';ctx.lineWidth=Math.max(2,scale*3);ctx.stroke();
+// colored piece highlights
+let x0=0;track.forEach(t=>{let p=pieces.find(q=>q.id===t.id);let end=x0+100;ctx.beginPath();let started=false;for(let q of smooth){if(q.x>=x0&&q.x<=end){if(!started){ctx.moveTo(sx(q.x),sy(q.y));started=true}else ctx.lineTo(sx(q.x),sy(q.y))}}ctx.strokeStyle=p.color;ctx.globalAlpha=.88;ctx.lineWidth=Math.max(2,scale*3);ctx.stroke();ctx.globalAlpha=1;x0=end});
+// start and flag
+ctx.fillStyle='#c8f36a';ctx.beginPath();ctx.arc(sx(0),sy(0),5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f6d276';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(sx(r.width-30),sy(0)-5);ctx.lineTo(sx(r.width-30),sy(0)-32);ctx.lineTo(sx(r.width-11),sy(0)-25);ctx.lineTo(sx(r.width-30),sy(0)-18);ctx.stroke();
+// car
+let at=running?progress:Math.min(7,r.width*.015);let nearest=0;for(let i=1;i<smooth.length;i++){if(smooth[i].x>=at){nearest=i;break}}let a=smooth[Math.max(0,nearest-1)],b=smooth[Math.min(smooth.length-1,nearest+1)],car=smooth[Math.min(smooth.length-1,nearest)],angle=Math.atan2(-(b.y-a.y),b.x-a.x);let cx=sx(car.x),cy=sy(car.y)-scale*9;
+ctx.save();ctx.translate(cx,cy);ctx.rotate(angle);ctx.fillStyle='#17263a';roundedRect(-13*scale,-8*scale,28*scale,12*scale,4*scale);ctx.fill();ctx.fillStyle='#f56f87';roundedRect(-11*scale,-10*scale,24*scale,10*scale,4*scale);ctx.fill();ctx.fillStyle='#ffe2a3';ctx.beginPath();ctx.arc(-5*scale,-13*scale,3.2*scale,0,Math.PI*2);ctx.arc(4*scale,-13*scale,3.2*scale,0,Math.PI*2);ctx.fill();ctx.fillStyle='#27334a';ctx.beginPath();ctx.arc(-7*scale,5*scale,3*scale,0,Math.PI*2);ctx.arc(9*scale,5*scale,3*scale,0,Math.PI*2);ctx.fill();ctx.restore();
+// status mini label in test mode
+if(running){ctx.fillStyle='#142033dd';roundedRect(cw-116,54,102,25,8);ctx.fill();ctx.fillStyle='#c8f36a';ctx.font='800 10px system-ui';ctx.fillText(`${Math.round(carSpeed)} KM/H`,cw-103,70)}
+}
+
