if(running){ctx.fillStyle='#142033dd';roundedRect(cw-116,54,102,25,8);ctx.fill();ctx.fillStyle='#c8f36a';ctx.font='800 10px system-ui';ctx.fillText(`${Math.round(carSpeed)} KM/H`,cw-103,70)}
}
function startRide(){if(!track.length){notify('Add a track piece before you test your ride.');return}$('#testOverlay').classList.remove('show');running=true;progress=0;airAccum=0;maxSpeed=0;carSpeed=55;lastTime=performance.now();$('#sceneLabel').textContent='LIVE TEST RUN';$('#canvasHint').innerHTML='<b>LIVE</b> &nbsp;Hold on tight — your ride is in motion!';$('#testBtn').textContent='■  Ride in progress';$('#testBtn').disabled=true;draw();raf=requestAnimationFrame(tick)}
function tick(now){if(!running)return;let dt=Math.min(.05,(now-lastTime)/1000);lastTime=now;let rt=route(),v=55;
for(let i=0;i<track.length;i++){let p=pieces.find(q=>q.id===track[i].id),start=i*100;if(progress>=start&&progress<=start+100){v+=p.speed*.8;if(p.id==='drop'||p.id==='jump')v+=12;if(p.id==='brake')v-=28;break}}
let elevation=0;for(let i=0;i<rt.pts.length;i++){if(rt.pts[i].x>=progress){elevation=rt.pts[i].y;break}}v+=Math.max(0,elevation*.06);carSpeed=Math.max(36,Math.min(190,v));maxSpeed=Math.max(maxSpeed,carSpeed);if(track.some((t,i)=>t.id==='jump'&&progress>=i*100+25&&progress<=i*100+75))airAccum+=dt;progress+=carSpeed*.95*dt;draw();if(progress>=rt.width){finishRide();return}raf=requestAnimationFrame(tick)}
function finishRide(){running=false;cancelAnimationFrame(raf);$('#testBtn').disabled=false;$('#testBtn').textContent='▶  Test your coaster';$('#sceneLabel').textContent='TEST COMPLETE';$('#canvasHint').innerHTML='<b>FINISH</b> &nbsp;What a ride! Tweak your track or ride again.';let unique=new Set(track.map(t=>t.id)).size,thrill=42;track.forEach(t=>thrill+=pieces.find(p=>p.id===t.id).thrill);let score=Math.round(Math.min(100,thrill)*7+unique*14+Math.min(maxSpeed,160)*.5+airAccum*18);let rating=score>830?'S+':score>720?'S':score>580?'A':score>430?'B':'C';$('#resultIcon').textContent=rating==='S+'?'🏆':'🎢';$('#resultTitle').textContent=rating==='S+'?'Park legend!':'Ride complete!';$('#resultText').textContent=rating==='S+'?'You just designed a coaster worthy of the Hall of Thrills.':'Your train made it home in one piece. Add variety and airtime to boost your park rating.';$('#resultScore').textContent=score.toLocaleString();$('#resultSpeed').textContent=Math.round(maxSpeed)+' km/h';$('#resultAir').textContent=airAccum.toFixed(1)+'s';$('#resultRating').textContent=rating;$('#testOverlay').classList.add('show');draw()}
function stopRide(){running=false;cancelAnimationFrame(raf);$('#testBtn').disabled=false;$('#sceneLabel').textContent='DESIGN VIEW';$('#canvasHint').innerHTML='<b>TIP</b> &nbsp;Add a loop for a thrill boost';$('#testOverlay').classList.remove('show');draw()}
function notify(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function reset(){stopRide();seedTrack();updateUI();draw();notify('Starter coaster restored.')}
